const CIRC=2*Math.PI*100;let COLORS={work:'#f87171',short:'#6ee7b7',long:'#93bbfd'};const LABELS={work:'FOCUS',short:'SHORT BREAK',long:'LONG BREAK'};let durations={work:25,short:5,long:15};let mode='work',timeLeft=durations.work*60,totalTime=timeLeft,running=false,timer=null,sessions=0,focusTotal=0,autoAdvance=false,audioCtx=null;const $=id=>document.getElementById(id);function fmt(s){return`${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`}function render(){$('display').textContent=fmt(timeLeft);$('label').textContent=LABELS[mode];const pct=timeLeft/totalTime;$('progress').style.strokeDashoffset=CIRC*(1-pct);$('progress').style.stroke=COLORS[mode];$('sessions').textContent=sessions;$('totalMin').textContent=Math.floor(focusTotal/60)+'m';const pb=$('playBtn');pb.classList.toggle('running',running);if(!running)pb.style.background=COLORS[mode];else pb.style.background='#fbbf24';$('playIcon').style.display=running?'none':'block';$('pauseIcon').style.display=running?'block':'none';document.title=`${fmt(timeLeft)} - ${LABELS[mode]}`}function setMode(m){mode=m;timeLeft=durations[m]*60;totalTime=timeLeft;running=false;clearInterval(timer);timer=null;document.querySelectorAll('.mode-btn').forEach(b=>b.classList.toggle('active',b.dataset.mode===m));render()}function playChime(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();const now=audioCtx.currentTime;[523.25,659.25,783.99].forEach((f,i)=>{const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);o.frequency.value=f;o.type='sine';g.gain.setValueAtTime(.12,now+i*.15);g.gain.exponentialRampToValueAtTime(.001,now+i*.15+.5);o.start(now+i*.15);o.stop(now+i*.15+.6)})}function tick(){if(timeLeft>0){timeLeft--;if(mode==='work')focusTotal++;render()}else{clearInterval(timer);timer=null;running=false;playChime();if(mode==='work'){sessions++;const next=sessions%4===0?'long':'short';if(autoAdvance){setMode(next);toggle()}else{setMode(next)}}else{if(autoAdvance){setMode('work');toggle()}else{setMode('work')}}}}function toggle(){if(!audioCtx)audioCtx=new(window.AudioContext||window.webkitAudioContext)();if(running){running=false;clearInterval(timer);timer=null}else{running=true;timer=setInterval(tick,1000)}render()}$('playBtn').addEventListener('click',toggle);$('resetBtn').addEventListener('click',()=>{running=false;clearInterval(timer);timer=null;timeLeft=durations[mode]*60;totalTime=timeLeft;render()});document.querySelectorAll('.mode-btn').forEach(b=>b.addEventListener('click',()=>setMode(b.dataset.mode)));document.querySelectorAll('.adj').forEach(b=>b.addEventListener('click',()=>{const t=b.dataset.t,d=parseInt(b.dataset.d);durations[t]=Math.max(1,Math.min(60,durations[t]+d));$(t+'-val').textContent=durations[t];if(t===mode&&!running){timeLeft=durations[t]*60;totalTime=timeLeft;render()}}));$('autoToggle').addEventListener('click',()=>{autoAdvance=!autoAdvance;$('autoToggle').textContent=autoAdvance?'On':'Off';$('autoToggle').classList.toggle('on',autoAdvance)});document.addEventListener('keydown',e=>{if(e.code==='Space'){e.preventDefault();toggle()}else if(e.code==='KeyR'){running=false;clearInterval(timer);timer=null;timeLeft=durations[mode]*60;totalTime=timeLeft;render()}});

/* ---- Background system ---- */
const canvas=$('bgCanvas'),ctx=canvas.getContext('2d');let activeBg='waves';
function resizeCvs(){canvas.width=window.innerWidth;canvas.height=window.innerHeight;if(bgs[activeBg].init)bgs[activeBg].init()}
window.addEventListener('resize',resizeCvs);

const bgs={
  none:{init(){},draw(){ctx.fillStyle='#111117';ctx.fillRect(0,0,canvas.width,canvas.height)}},

  waves:{t:0,init(){this.t=0},draw(){
    const w=canvas.width,h=canvas.height;
    ctx.fillStyle='rgba(14,14,20,0.12)';ctx.fillRect(0,0,w,h);
    this.t+=0.006;
    for(let i=0;i<5;i++){
      ctx.beginPath();ctx.moveTo(0,h);
      const base=h*0.45+i*55,amp=25+i*12,freq=0.0025-i*0.0004,spd=this.t*(1+i*0.15);
      for(let x=0;x<=w;x+=4){
        const y=base+Math.sin(x*freq+spd)*amp+Math.sin(x*freq*2.3+spd*1.4)*(amp*0.35);
        ctx.lineTo(x,y)}
      ctx.lineTo(w,h);ctx.closePath();
      const hue=activeTheme.bgHue[mode]+i*8;
      ctx.fillStyle=`hsla(${hue},50%,45%,${0.07-i*0.012})`;ctx.fill()}
  }},

  aurora:{t:0,init(){this.t=0},draw(){
    const w=canvas.width,h=canvas.height;this.t+=0.002;
    const g=ctx.createLinearGradient(w*0.5+Math.sin(this.t)*w*0.3,0,w*0.5+Math.cos(this.t*0.7)*w*0.3,h);
    const hBase=activeTheme.bgHue[mode];
    g.addColorStop(0,`hsla(${hBase},45%,12%,1)`);
    g.addColorStop(0.5,`hsla(${(hBase+30)%360},40%,9%,1)`);
    g.addColorStop(1,`hsla(${(hBase+60)%360},45%,12%,1)`);
    ctx.fillStyle=g;ctx.fillRect(0,0,w,h);
    for(let i=0;i<4;i++){
      ctx.beginPath();const y=h*0.25+i*70;
      for(let x=0;x<=w;x+=8){
        const wave=Math.sin(x*0.004+this.t*2+i)*45+Math.sin(x*0.009+this.t*2.5)*18;
        ctx.lineTo(x,y+wave)}
      ctx.lineTo(w,y+90);ctx.lineTo(0,y+90);ctx.closePath();
      ctx.fillStyle=`hsla(${(hBase+i*25)%360},65%,50%,0.04)`;ctx.fill()}
  }},

  stars:{pts:[],t:0,init(){this.pts=[];this.t=0;
    for(let i=0;i<180;i++)this.pts.push({x:Math.random()*canvas.width,y:Math.random()*canvas.height,s:Math.random()*2+0.5,sp:Math.random()*0.015+0.005,o:Math.random()*Math.PI*2})},
  draw(){
    const w=canvas.width,h=canvas.height;
    const g=ctx.createLinearGradient(0,0,0,h);g.addColorStop(0,'#08080f');g.addColorStop(1,'#151520');
    ctx.fillStyle=g;ctx.fillRect(0,0,w,h);this.t+=0.016;
    this.pts.forEach(p=>{const tw=Math.sin(this.t*p.sp*60+p.o);
      ctx.beginPath();ctx.arc(p.x,p.y,p.s*(0.8+tw*0.2),0,Math.PI*2);
      ctx.fillStyle=`rgba(210,220,255,${0.25+tw*0.4})`;ctx.fill()})
  }},

  rain:{drops:[],init(){this.drops=[];
    for(let i=0;i<120;i++)this.drops.push({x:Math.random()*canvas.width,y:Math.random()*canvas.height,sp:Math.random()*3.5+1.5,len:Math.random()*18+8,a:Math.random()*0.25+0.08})},
  draw(){
    const w=canvas.width,h=canvas.height;
    ctx.fillStyle='rgba(12,14,22,0.18)';ctx.fillRect(0,0,w,h);
    const hue=activeTheme.bgHue[mode];
    this.drops.forEach(d=>{d.y+=d.sp;if(d.y>h){d.y=-d.len;d.x=Math.random()*w}
      ctx.beginPath();ctx.moveTo(d.x,d.y);ctx.lineTo(d.x,d.y+d.len);
      ctx.strokeStyle=`hsla(${hue},40%,65%,${d.a})`;ctx.lineWidth=1;ctx.stroke()})
  }},

  particles:{pts:[],init(){this.pts=[];
    for(let i=0;i<70;i++)this.pts.push({x:Math.random()*canvas.width,y:Math.random()*canvas.height,vx:(Math.random()-0.5)*0.25,vy:(Math.random()-0.5)*0.25,s:Math.random()*2.5+1,a:Math.random()*0.4+0.15})},
  draw(){
    const w=canvas.width,h=canvas.height;
    ctx.fillStyle='rgba(14,14,20,0.06)';ctx.fillRect(0,0,w,h);
    const hue=activeTheme.bgHue[mode];
    this.pts.forEach(p=>{p.x+=p.vx;p.y+=p.vy;if(p.x<0)p.x=w;if(p.x>w)p.x=0;if(p.y<0)p.y=h;if(p.y>h)p.y=0;
      ctx.beginPath();ctx.arc(p.x,p.y,p.s,0,Math.PI*2);ctx.fillStyle=`hsla(${hue},50%,70%,${p.a})`;ctx.fill()});
    ctx.strokeStyle=`hsla(${hue},40%,60%,0.04)`;ctx.lineWidth=1;
    for(let i=0;i<this.pts.length;i++)for(let j=i+1;j<this.pts.length;j++){
      const dx=this.pts[i].x-this.pts[j].x,dy=this.pts[i].y-this.pts[j].y;
      if(Math.sqrt(dx*dx+dy*dy)<110){ctx.beginPath();ctx.moveTo(this.pts[i].x,this.pts[i].y);ctx.lineTo(this.pts[j].x,this.pts[j].y);ctx.stroke()}}
  }}
};

function setBg(id){activeBg=id;document.querySelectorAll('.bg-btn').forEach(b=>b.classList.toggle('active',b.dataset.bg===id));if(bgs[id].init)bgs[id].init()}
function animBg(){if(bgs[activeBg])bgs[activeBg].draw();requestAnimationFrame(animBg)}

/* Build bg picker buttons */
const bgNames={none:'None',waves:'Waves',aurora:'Aurora',stars:'Stars',rain:'Rain',particles:'Particles'};
Object.keys(bgNames).forEach(id=>{const b=document.createElement('button');b.className='bg-btn'+(id===activeBg?' active':'');b.textContent=bgNames[id];b.dataset.bg=id;b.addEventListener('click',()=>setBg(id));$('bgPicker').appendChild(b)});

