  {id:'cyan',swatch:'#22d3ee',work:'#22d3ee',short:'#f97316',long:'#c084fc',workTab:'rgba(34,211,238,.25)',shortTab:'rgba(249,115,22,.25)',longTab:'rgba(192,132,252,.25)',workTabText:'#22d3ee',shortTabText:'#f97316',longTabText:'#c084fc',bgHue:{work:185,short:25,long:275}},
  {id:'pink',swatch:'#f472b6',work:'#f472b6',short:'#38bdf8',long:'#a3e635',workTab:'rgba(244,114,182,.25)',shortTab:'rgba(56,189,248,.25)',longTab:'rgba(163,230,53,.25)',workTabText:'#f472b6',shortTabText:'#38bdf8',longTabText:'#a3e635',bgHue:{work:330,short:200,long:80}}
];
let activeTheme=colorThemes[0];
function setTheme(theme){activeTheme=theme;COLORS={work:theme.work,short:theme.short,long:theme.long};
  const pb=$('playBtn');pb.style.background=running?'#fbbf24':theme.work;
  document.querySelectorAll('.color-swatch').forEach(s=>s.classList.toggle('active',s.dataset.theme===theme.id));
  /* Update mode tab colors via CSS custom properties */
  const style=document.documentElement.style;
  style.setProperty('--work-tab-bg',theme.workTab);style.setProperty('--work-tab-c',theme.workTabText);
  style.setProperty('--short-tab-bg',theme.shortTab);style.setProperty('--short-tab-c',theme.shortTabText);
  style.setProperty('--long-tab-bg',theme.longTab);style.setProperty('--long-tab-c',theme.longTabText);
  render()}
colorThemes.forEach(t=>{const s=document.createElement('button');s.className='color-swatch'+(t.id===activeTheme.id?' active':'');s.style.background=t.swatch;s.dataset.theme=t.id;s.addEventListener('click',()=>setTheme(t));$('colorPicker').appendChild(s)});

$('settingsToggle').addEventListener('click',()=>{const p=$('settingsPanel'),t=$('settingsToggle');const open=p.classList.contains('expanded');p.classList.toggle('collapsed',!open?false:true);p.classList.toggle('expanded',!open);t.classList.toggle('open',!open)});

